begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create temp table source_audit_baseline as select count(*)::int as n from public.audit_logs where table_name='offers' and row_id='ef190000-0000-4000-8000-000000000001';
insert into auth.users(id,instance_id,aud,role,email) select ('ab190000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','export-'||n||'@example.invalid' from generate_series(1,4) n;
insert into public.staff_users(user_id,role) values('ab190000-0000-4000-8000-000000000001','office'),('ab190000-0000-4000-8000-000000000002','admin'),('ab190000-0000-4000-8000-000000000003','technician');
insert into public.customers(id,name) values('cc190000-0000-4000-8000-000000000001','Klient konwersji');
insert into public.catalog_items(id,code,name,category,unit,cost_cents,sale_cents,vat_basis_points,created_by,created_payload,archived) values
('cd190000-0000-4000-8000-000000000001','EXPORT-1','Praca','service','hour',100,200,2300,'ab190000-0000-4000-8000-000000000001','{}',false),
('cd190000-0000-4000-8000-000000000002','EXPORT-2','Materiał','material','meter',100,200,2300,'ab190000-0000-4000-8000-000000000001','{}',false);
create function pg_temp.line(n integer,catalog text default null) returns jsonb language sql as $$select jsonb_build_object('id','df190000-0000-4000-8000-'||lpad(n::text,12,'0'),'catalogId',catalog,'code','PRIVATE CODE','name','Źródłowa praca '||n,'description','PRIVATE DESCRIPTION','category','service','unit','hour','quantityMills',6000,'costCents',321,'saleCents',1000,'vatBasisPoints',800,'discountBasisPoints',1000)$$;
create function pg_temp.offer() returns jsonb language sql as $$select jsonb_build_object('customerId','cc190000-0000-4000-8000-000000000001','locationId',null,'title','PRIVATE CUSTOMER TITLE','workType','split','technical',jsonb_build_object('lengthMills',8000,'laborMills',6000,'travelMills',0),'mainVariantId','dd190000-0000-4000-8000-000000000001','archived',false,'variants',jsonb_build_array(jsonb_build_object('id','dd190000-0000-4000-8000-000000000001','name','Komfort','internalNote','PRIVATE INTERNAL','customerNote','PRIVATE CUSTOMER','targetMarginBasisPoints',4000,'overrideNetCents',10000,'lines',jsonb_build_array(pg_temp.line(1,'cd190000-0000-4000-8000-000000000001'),pg_temp.line(2)))))$$;
create function pg_temp.input(n integer default 1,version integer default 0) returns jsonb language sql as $$select jsonb_build_object('id','ee190000-0000-4000-8000-'||lpad(n::text,12,'0'),'offerVersion',version,'name','Powtarzalny montaż','description','','mappings',jsonb_build_array(jsonb_build_object('lineId','df190000-0000-4000-8000-000000000001','catalogId','cd190000-0000-4000-8000-000000000001'),jsonb_build_object('lineId','df190000-0000-4000-8000-000000000002','catalogId','cd190000-0000-4000-8000-000000000001')))$$;
create function pg_temp.context() returns jsonb language sql as $$select public.offer_variant_template_context('ef190000-0000-4000-8000-000000000001','dd190000-0000-4000-8000-000000000001')$$;
create function pg_temp.convert(input jsonb default pg_temp.input()) returns jsonb language sql as $$select public.create_template_from_offer_variant('ef190000-0000-4000-8000-000000000001','dd190000-0000-4000-8000-000000000001',input)$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','ab190000-0000-4000-8000-000000000001',true);
select public.save_offer('ef190000-0000-4000-8000-000000000001',pg_temp.offer(),null);
select is(pg_temp.context()->'lines'->0->'catalog'->>'id','cd190000-0000-4000-8000-000000000001','Active matching-unit link suggested');
select is(pg_temp.context()->'lines'->1->'catalog','null'::jsonb,'Manual line requires explicit link');
select ok(pg_temp.context()::text not like '%PRIVATE%','Context excludes costs, descriptions, customer title and notes');
select throws_ok($$select pg_temp.convert(jsonb_set(pg_temp.input(),'{offerVersion}','1'))$$,'40001',null,'Stale source denied');
select throws_ok($$select pg_temp.convert(jsonb_set(pg_temp.input(),'{mappings}',jsonb_build_array(pg_temp.input()->'mappings'->0)))$$,'22023',null,'No silent omission');
select throws_ok($$select pg_temp.convert(jsonb_set(pg_temp.input(),'{mappings}',jsonb_build_array(pg_temp.input()->'mappings'->0,pg_temp.input()->'mappings'->0)))$$,'22023',null,'Repeated line mapping denied');
select throws_ok($$select pg_temp.convert(jsonb_set(pg_temp.input(),'{mappings,1,lineId}','"df190000-0000-4000-8000-000000000099"'))$$,'22023',null,'Foreign source line denied');
select throws_ok($$select pg_temp.convert(jsonb_set(pg_temp.input(),'{mappings,1,catalogId}','"cd190000-0000-4000-8000-000000000002"'))$$,'22023',null,'Unit mismatch denied');
select throws_ok($$select pg_temp.convert(pg_temp.input()||'{"quantityMills":1}')$$,'22023',null,'Forged source quantity denied');
select is(jsonb_array_length(pg_temp.convert()->'fields'->'lines'),2,'All source rows converted');
select is(pg_temp.convert()->'fields'->'lines'->0->>'quantityMills','6000','Saved source quantity retained');
select is(pg_temp.convert()->'fields'->'lines'->0->>'quantitySource','fixed','Computed quantity becomes fixed');
select isnt(pg_temp.convert()->'fields'->'lines'->0->>'id','df190000-0000-4000-8000-000000000001','New line identity');
select ok(pg_temp.convert()::text not like '%PRIVATE%' and pg_temp.convert()::text not like '%saleCents%' and pg_temp.convert()::text not like '%overrideNetCents%','No prices, discounts, descriptions or private notes copied');
select is(public.installation_template_detail('ee190000-0000-4000-8000-000000000001')->'lines'->0->>'saleCents','200','Future template resolves current catalog price, not source price');
select is(public.offer_detail('ef190000-0000-4000-8000-000000000001')->>'version','0','Source version unchanged');
reset role;
select is((select count(*)::int from public.audit_logs where table_name='offers' and row_id='ef190000-0000-4000-8000-000000000001'),(select n+1 from source_audit_baseline),'No source update audit');
select is((select count(*)::int from public.audit_logs where table_name='installation_templates' and row_id='ee190000-0000-4000-8000-000000000001'),1,'Conversion retry creates one template audit');
select is((select count(*)::int from public.offer_template_exports where template_id='ee190000-0000-4000-8000-000000000001'),1,'One retry ledger record');
set local role authenticated;
select throws_ok($$select pg_temp.convert(jsonb_set(pg_temp.input(),'{name}','"Different"'))$$,'40001',null,'Same request id with different input denied');
select public.save_offer('ef190000-0000-4000-8000-000000000001',pg_temp.offer()||'{"archived":true}',0);
select is(pg_temp.convert()->>'version','0','Exact retry works after source changed');
select is(pg_temp.convert(pg_temp.input(2,1))->>'version','0','Archived saved source may create new template');
reset role;
update public.catalog_items set archived=true where id='cd190000-0000-4000-8000-000000000001';
set local role authenticated;
select is(pg_temp.context()->'lines'->0->'catalog','null'::jsonb,'Archived catalog link no longer suggested');
select throws_ok($$select pg_temp.convert(pg_temp.input(3,1))$$,'22023',null,'Catalog activity rechecked on save');
reset role;
select is((select count(*)::int from public.installation_templates where id='ee190000-0000-4000-8000-000000000003'),0,'Rejected conversion leaves no partial template');
set local role authenticated;
select set_config('request.jwt.claim.sub','ab190000-0000-4000-8000-000000000002',true);
select is(pg_temp.context()->>'offerVersion','1','Admin may read archived source');
select throws_ok($$select pg_temp.convert()$$,'40001',null,'Another actor cannot replay original request');
select set_config('request.jwt.claim.sub','ab190000-0000-4000-8000-000000000003',true);
select throws_ok($$select pg_temp.context()$$,'42501',null,'Technician denied context');
select throws_ok($$select pg_temp.convert()$$,'42501',null,'Technician denied creation');
select set_config('request.jwt.claim.sub','ab190000-0000-4000-8000-000000000004',true);
select throws_ok($$select pg_temp.context()$$,'42501',null,'No internal role denied context');
reset role;
insert into public.account_access(user_id,blocked) values('ab190000-0000-4000-8000-000000000001',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','ab190000-0000-4000-8000-000000000001',true);
select throws_ok($$select pg_temp.convert()$$,'42501',null,'Blocked office denied even exact retry');
select throws_ok($$select * from public.offer_template_exports$$,'42501',null,'Request ledger not exposed');
reset role;
set local role anon;
select throws_ok($$select public.offer_variant_template_context('ef190000-0000-4000-8000-000000000001','dd190000-0000-4000-8000-000000000001')$$,'42501',null,'Anonymous execution denied');
select * from finish();
rollback;
